import{_ as e,o as t,c as o,a2 as s}from"./chunks/framework.C0KMm31j.js";const n="/Nav2ArticlesSite/article-assets/2026-07-27/theta_star_core_01_overview.png",c="/Nav2ArticlesSite/article-assets/2026-07-27/theta_star_core_02_parent_rewire.png",i="/Nav2ArticlesSite/article-assets/2026-07-27/theta_star_core_03_search_loop.png",r="/Nav2ArticlesSite/article-assets/2026-07-27/theta_star_core_04_line_of_sight.png",d="/Nav2ArticlesSite/article-assets/2026-07-27/theta_star_core_05_cost_model.png",p="/Nav2ArticlesSite/article-assets/2026-07-27/theta_star_core_06_backtrace_output.png",q=JSON.parse('{"title":"A* 为什么非要一格一格拐？Nav2 Theta* 用一条视线把路径拉直","description":"普通栅格 A 即使找到了最短路，也常交出一条“横一下、斜一下”的折线。问题不在 A 不会算最短路，而在搜索图只允许节点连接有限个相邻栅格：父指针被锁在四邻域或八邻域里，最终路径自然带着网格方向的痕迹。","frontmatter":{"title":"A* 为什么非要一格一格拐？Nav2 Theta* 用一条视线把路径拉直","description":"普通栅格 A 即使找到了最短路，也常交出一条“横一下、斜一下”的折线。问题不在 A 不会算最短路，而在搜索图只允许节点连接有限个相邻栅格：父指针被锁在四邻域或八邻域里，最终路径自然带着网格方向的痕迹。","date":"2026-07-27","topic":"Nav2 工程实践","section":"二 · 全局规划与路径搜索","readingTime":11,"source":"2026-07-27/nav2_theta_star_planner_core_algorithm.md","status":"published","cover":"/article-assets/2026-07-27/theta_star_core_01_overview.png","head":[["link",{"rel":"canonical","href":"https://zpy560.github.io/Nav2ArticlesSite/nav2/nav2-theta-star-planner-core-algorithm"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"A* 为什么非要一格一格拐？Nav2 Theta* 用一条视线把路径拉直"}],["meta",{"property":"og:description","content":"普通栅格 A 即使找到了最短路，也常交出一条“横一下、斜一下”的折线。问题不在 A 不会算最短路，而在搜索图只允许节点连接有限个相邻栅格：父指针被锁在四邻域或八邻域里，最终路径自然带着网格方向的痕迹。"}],["meta",{"property":"og:url","content":"https://zpy560.github.io/Nav2ArticlesSite/nav2/nav2-theta-star-planner-core-algorithm"}],["meta",{"property":"og:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-07-27/theta_star_core_01_overview.png"}],["meta",{"property":"article:published_time","content":"2026-07-27"}],["meta",{"name":"twitter:title","content":"A* 为什么非要一格一格拐？Nav2 Theta* 用一条视线把路径拉直"}],["meta",{"name":"twitter:description","content":"普通栅格 A 即使找到了最短路，也常交出一条“横一下、斜一下”的折线。问题不在 A 不会算最短路，而在搜索图只允许节点连接有限个相邻栅格：父指针被锁在四邻域或八邻域里，最终路径自然带着网格方向的痕迹。"}],["meta",{"name":"twitter:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-07-27/theta_star_core_01_overview.png"}]],"prev":{"text":"A* 不只会“走格子”：Nav2 Smac Planner 如何把转弯半径、倒车与避障写进搜索？","link":"/nav2/nav2-smac-planner-core-algorithm"},"next":{"text":"路径会被障碍“拽弯”，时间还会自己收缩：Nav2 TEB 图优化核心拆解","link":"/nav2/teb-local-planner-core-algorithm"}},"headers":[],"relativePath":"nav2/nav2-theta-star-planner-core-algorithm.md","filePath":"nav2/nav2-theta-star-planner-core-algorithm.md","lastUpdated":null}'),l={name:"nav2/nav2-theta-star-planner-core-algorithm.md"};function h(_,a,u,b,m,g){return t(),o("div",null,[...a[0]||(a[0]=[s('<h1 id="a-为什么非要一格一格拐-nav2-theta-用一条视线把路径拉直" tabindex="-1">A* 为什么非要一格一格拐？Nav2 Theta* 用一条视线把路径拉直 <a class="header-anchor" href="#a-为什么非要一格一格拐-nav2-theta-用一条视线把路径拉直" aria-label="Permalink to &quot;A* 为什么非要一格一格拐？Nav2 Theta* 用一条视线把路径拉直&quot;">​</a></h1><p>普通栅格 A* 即使找到了最短路，也常交出一条“横一下、斜一下”的折线。问题不在 A* 不会算最短路，而在搜索图只允许节点连接有限个相邻栅格：父指针被锁在四邻域或八邻域里，最终路径自然带着网格方向的痕迹。</p><p>Nav2 Theta* 保留 A* 的开放队列、<code>g+h</code> 和父指针，却在节点真正展开前多问一句：当前节点能否直接看见父节点的父节点？如果中间无遮挡，而且直连更便宜，就跳过原父节点。一个局部重连动作，便把栅格折线拉成了任意角路径。</p><p>本文基于当前本地 <code>navigation2@03db095</code>、<code>nav2_theta_star_planner 1.1.20</code> 源码、测试与现用参数，只拆 Lazy Theta* P 的核心搜索、视线检查、代价函数、容器状态、回溯与实现边界。</p><p><img src="'+n+'" alt="Theta* 核心算法总览"></p><h2 id="一、theta-改的不是-a-而是父节点关系" tabindex="-1">一、Theta* 改的不是 A*，而是父节点关系 <a class="header-anchor" href="#一、theta-改的不是-a-而是父节点关系" aria-label="Permalink to &quot;一、Theta* 改的不是 A*，而是父节点关系&quot;">​</a></h2><h3 id="_1-1-普通-a-的路径为什么带栅格味" tabindex="-1">1.1 普通 A* 的路径为什么带栅格味 <a class="header-anchor" href="#_1-1-普通-a-的路径为什么带栅格味" aria-label="Permalink to &quot;1.1 普通 A* 的路径为什么带栅格味&quot;">​</a></h3><p>四邻域 A* 每次只能上下左右移动，八邻域再增加四个对角方向。无论启发函数多聪明，新节点的父节点都只能是直接扩展它的相邻节点。</p><p>因此，开放空间中的一条真实直线，会被离散成水平、垂直和四十五度斜线的组合。地图分辨率越粗，折线感越明显。</p><h3 id="_1-2-theta-允许跨过相邻节点" tabindex="-1">1.2 Theta* 允许跨过相邻节点 <a class="header-anchor" href="#_1-2-theta-允许跨过相邻节点" aria-label="Permalink to &quot;1.2 Theta* 允许跨过相邻节点&quot;">​</a></h3><p>设当前节点为 <code>s</code>，它的父节点为 <code>p</code>，祖父节点为 <code>q</code>。普通 A* 保留：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>q → p → s</span></span></code></pre></div><p>Theta* 会检查 <code>q</code> 到 <code>s</code> 的直线。如果沿线安全，并且：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>g(q) + line_cost(q,s) &lt; g(s)</span></span></code></pre></div><p>就把父链改成：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>q ─────────→ s</span></span></code></pre></div><p><code>p</code> 没有从搜索图消失，只是不再是 <code>s</code> 的最优父节点。不断发生的局部“抄近路”，最终形成少折点的任意角父链。</p><h3 id="_1-3-当前实现是-lazy-theta-p" tabindex="-1">1.3 当前实现是 Lazy Theta* P <a class="header-anchor" href="#_1-3-当前实现是-lazy-theta-p" aria-label="Permalink to &quot;1.3 当前实现是 Lazy Theta* P&quot;">​</a></h3><p>经典 Theta* 常在生成邻居时执行视线检查。当前源码采用 Lazy Theta* P 风格：邻居先按普通相邻边入队，等它成为待扩展节点后，<code>resetParent()</code> 才尝试连接祖父节点。</p><p>这减少了对所有候选邻居立即做视线检查的次数。代价是父节点修正发生得更晚，必须准确理解“入队”和“出队展开”两个时刻。</p><p><img src="'+c+'" alt="普通 A* 与 Lazy Theta* 父节点重连"></p><h2 id="二、一个搜索节点究竟保存什么" tabindex="-1">二、一个搜索节点究竟保存什么 <a class="header-anchor" href="#二、一个搜索节点究竟保存什么" aria-label="Permalink to &quot;二、一个搜索节点究竟保存什么&quot;">​</a></h2><h3 id="_2-1-tree-node-是算法的最小状态" tabindex="-1">2.1 <code>tree_node</code> 是算法的最小状态 <a class="header-anchor" href="#_2-1-tree-node-是算法的最小状态" aria-label="Permalink to &quot;2.1 `tree_node` 是算法的最小状态&quot;">​</a></h3><p>每个节点保存：</p><ul><li>栅格坐标 <code>x</code>、<code>y</code>。</li><li>起点累计代价 <code>g</code>。</li><li>到目标的启发代价 <code>h</code>。</li><li>总优先级 <code>f=g+h</code>。</li><li>父节点指针 <code>parent_id</code>。</li><li>当前是否在优先队列中的 <code>is_in_queue</code>。</li></ul><p>起点的父指针指向自己。回溯遇到“父节点就是自身”时，便知道已经到达根节点。</p><h3 id="_2-2-node-position-负责按栅格查节点" tabindex="-1">2.2 <code>node_position_</code> 负责按栅格查节点 <a class="header-anchor" href="#_2-2-node-position-负责按栅格查节点" aria-label="Permalink to &quot;2.2 `node_position_` 负责按栅格查节点&quot;">​</a></h3><p>算法没有为整张图构造完整节点对象。<code>node_position_[width*y+x]</code> 保存该栅格对应的 <code>tree_node*</code>；未发现的栅格为 <code>nullptr</code>。</p><p>这张索引表负责快速回答“这个栅格以前见过吗”。真正被搜索到的节点连续存入 <code>nodes_data_</code>。</p><h3 id="_2-3-nodes-data-提供稳定节点存储" tabindex="-1">2.3 <code>nodes_data_</code> 提供稳定节点存储 <a class="header-anchor" href="#_2-3-nodes-data-提供稳定节点存储" aria-label="Permalink to &quot;2.3 `nodes_data_` 提供稳定节点存储&quot;">​</a></h3><p>地图尺寸初次出现或扩大时，源码按地图单元数为 <code>nodes_data_</code> 预留容量，避免搜索中扩容后指针失效。新栅格初次出现时才从这块连续存储中分配一个节点位置。</p><h3 id="_2-4-queue-决定下一次展开谁" tabindex="-1">2.4 <code>queue_</code> 决定下一次展开谁 <a class="header-anchor" href="#_2-4-queue-决定下一次展开谁" aria-label="Permalink to &quot;2.4 `queue_` 决定下一次展开谁&quot;">​</a></h3><p><code>queue_</code> 是按 <code>f</code> 从小到大弹出的优先队列。启发项让搜索倾向目标，累计代价又阻止它只顾眼前方向、不顾已经付出的路径成本。</p><p>这里没有独立的 Closed Set。节点展开时把 <code>is_in_queue</code> 置为 <code>false</code>；以后若发现更低代价，它仍可能再次入队。这个布尔量表达的是“是否在队列”，不是永久访问标记。</p><h2 id="三、主循环如何从起点推进到目标" tabindex="-1">三、主循环如何从起点推进到目标 <a class="header-anchor" href="#三、主循环如何从起点推进到目标" aria-label="Permalink to &quot;三、主循环如何从起点推进到目标&quot;">​</a></h2><h3 id="_3-1-起点也要支付栅格通行代价" tabindex="-1">3.1 起点也要支付栅格通行代价 <a class="header-anchor" href="#_3-1-起点也要支付栅格通行代价" aria-label="Permalink to &quot;3.1 起点也要支付栅格通行代价&quot;">​</a></h3><p>初始化时：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>g(start) = traversal_cost(start)</span></span>\n<span class="line"><span>h(start) = heuristic(start, goal)</span></span>\n<span class="line"><span>f(start) = g(start) + h(start)</span></span>\n<span class="line"><span>parent(start) = start</span></span></code></pre></div><p>随后起点进入优先队列和栅格索引表。</p><h3 id="_3-2-待扩展节点先尝试修正父节点" tabindex="-1">3.2 待扩展节点先尝试修正父节点 <a class="header-anchor" href="#_3-2-待扩展节点先尝试修正父节点" aria-label="Permalink to &quot;3.2 待扩展节点先尝试修正父节点&quot;">​</a></h3><p>主循环对当前节点执行 <code>resetParent()</code>。它读取：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>parent = current.parent</span></span>\n<span class="line"><span>maybe_parent = parent.parent</span></span></code></pre></div><p>若 <code>current</code> 与 <code>maybe_parent</code> 存在视线，就按整段直线重新计算 <code>g</code>。只有新值更低时，才修改父指针、<code>g</code> 和 <code>f</code>。</p><h3 id="_3-3-再扩展四邻域或八邻域" tabindex="-1">3.3 再扩展四邻域或八邻域 <a class="header-anchor" href="#_3-3-再扩展四邻域或八邻域" aria-label="Permalink to &quot;3.3 再扩展四邻域或八邻域&quot;">​</a></h3><p><code>how_many_corners=4</code> 时，算法只使用固定移动表前四项，也就是上下左右。设为 <code>8</code> 时，再加入四个对角邻居。</p><p>邻居必须同时满足地图边界与通行条件。候选累计代价更低时，算法更新邻居的 <code>g</code>、<code>h</code>、<code>f</code> 与父节点；若它当前不在队列，再压入优先队列。</p><h3 id="_3-4-目标必须成为当前节点" tabindex="-1">3.4 目标必须成为当前节点 <a class="header-anchor" href="#_3-4-目标必须成为当前节点" aria-label="Permalink to &quot;3.4 目标必须成为当前节点&quot;">​</a></h3><p>算法不是“发现目标邻居”就结束，而是等待目标成为当前节点，再进入回溯。开放队列耗尽则清空结果并报告失败。</p><p>当前现用配置为八邻域。八邻域只决定搜索图如何发现候选节点；任意角能力来自后续视线重连，不是来自对角移动本身。</p><p><img src="'+i+'" alt="Lazy Theta* 主循环与节点状态"></p><h2 id="四、视线检查如何判断一条直线能不能走" tabindex="-1">四、视线检查如何判断一条直线能不能走 <a class="header-anchor" href="#四、视线检查如何判断一条直线能不能走" aria-label="Permalink to &quot;四、视线检查如何判断一条直线能不能走&quot;">​</a></h2><h3 id="_4-1-它是带代价累计的-bresenham" tabindex="-1">4.1 它是带代价累计的 Bresenham <a class="header-anchor" href="#_4-1-它是带代价累计的-bresenham" aria-label="Permalink to &quot;4.1 它是带代价累计的 Bresenham&quot;">​</a></h3><p><code>losCheck(x0,y0,x1,y1,sl_cost)</code> 使用整数增量沿线推进，不需要把直线上的每个点转换成浮点坐标。</p><p>当横向跨度更大时，以 <code>x</code> 为主轴；纵向跨度更大时，以 <code>y</code> 为主轴。误差累计越过阈值时，副轴移动一个栅格。</p><h3 id="_4-2-检查结果不只是-通-或-不通" tabindex="-1">4.2 检查结果不只是“通”或“不通” <a class="header-anchor" href="#_4-2-检查结果不只是-通-或-不通" aria-label="Permalink to &quot;4.2 检查结果不只是“通”或“不通”&quot;">​</a></h3><p>每经过一个相关栅格，重载版 <code>isSafe()</code> 同时完成两件事：</p><ul><li>原始 Costmap 值为 <code>0～252</code> 时允许通过。</li><li>原始值为 <code>255</code> 时，只在 <code>allow_unknown=true</code> 时允许通过。</li><li>原始值为 <code>253</code> 或 <code>254</code> 时拒绝通过。</li><li>对允许通过的栅格，把穿越代价累加到 <code>sl_cost</code>。</li></ul><p>因此，两个端点之间即使都有视线，贴着膨胀层走的直线也可能比稍长但更居中的路线昂贵。</p><h3 id="_4-3-水平与垂直边界允许从一侧通过" tabindex="-1">4.3 水平与垂直边界允许从一侧通过 <a class="header-anchor" href="#_4-3-水平与垂直边界允许从一侧通过" aria-label="Permalink to &quot;4.3 水平与垂直边界允许从一侧通过&quot;">​</a></h3><p>直线恰好沿两排栅格的公共边界移动时，源码会检查边界两侧。只有两侧都不安全才拒绝这条线。</p><p>这是一种点机器人式的栅格可见性语义。算法本身不沿直线旋转并检查完整 Footprint，机器人外形依赖 Global Costmap 的 Inflation 预先编码。</p><h3 id="_4-4-未知区可走不等于便宜" tabindex="-1">4.4 未知区可走不等于便宜 <a class="header-anchor" href="#_4-4-未知区可走不等于便宜" aria-label="Permalink to &quot;4.4 未知区可走不等于便宜&quot;">​</a></h3><p>未知栅格允许通过时，LOS 累计代价把它按接近障碍的高值 <code>253</code> 处理。它能保证搜索在探索地图中仍有路可走，却不会把未知区当成普通自由空间。</p><p><img src="'+r+`" alt="Bresenham 视线检查与栅格通行语义"></p><h2 id="五、路径为何会在-最短-和-离障碍远-之间折中" tabindex="-1">五、路径为何会在“最短”和“离障碍远”之间折中 <a class="header-anchor" href="#五、路径为何会在-最短-和-离障碍远-之间折中" aria-label="Permalink to &quot;五、路径为何会在“最短”和“离障碍远”之间折中&quot;">​</a></h2><h3 id="_5-1-相邻扩展的累计代价" tabindex="-1">5.1 相邻扩展的累计代价 <a class="header-anchor" href="#_5-1-相邻扩展的累计代价" aria-label="Permalink to &quot;5.1 相邻扩展的累计代价&quot;">​</a></h3><p>从当前节点 <code>n</code> 走到邻居 <code>m</code>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>g_new(m) =</span></span>
<span class="line"><span>  g(n)</span></span>
<span class="line"><span>  + w_euc × hypot(mx-nx, my-ny)</span></span>
<span class="line"><span>  + w_traversal × ((26 + 0.9×C(m)) / 252)²</span></span></code></pre></div><p>其中 <code>C(m)</code> 是 Costmap 原始值。源码先把原始代价平移并缩放为 <code>26+0.9×C</code>，再归一化、平方。</p><p>自由栅格也不是零穿越成本，因为平移后至少为 <code>26</code>。靠近障碍时，平方项会快速放大差异。</p><h3 id="_5-2-祖父节点直连的累计代价" tabindex="-1">5.2 祖父节点直连的累计代价 <a class="header-anchor" href="#_5-2-祖父节点直连的累计代价" aria-label="Permalink to &quot;5.2 祖父节点直连的累计代价&quot;">​</a></h3><p>视线重连时：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>g_los(current) =</span></span>
<span class="line"><span>  g(grandparent)</span></span>
<span class="line"><span>  + w_euc × distance(grandparent,current)</span></span>
<span class="line"><span>  + LOS 沿线累计穿越代价</span></span></code></pre></div><p>只有 <code>g_los &lt; g(current)</code> 才采用祖父节点。能看见只是必要条件，直连还必须在完整代价模型下更划算。</p><h3 id="_5-3-启发项保持保守" tabindex="-1">5.3 启发项保持保守 <a class="header-anchor" href="#_5-3-启发项保持保守" aria-label="Permalink to &quot;5.3 启发项保持保守&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>h(n) = w_h × distance(n,goal)</span></span>
<span class="line"><span>w_h = min(w_euc, 1.0)</span></span>
<span class="line"><span>f(n) = g(n) + h(n)</span></span></code></pre></div><p>配置阶段把启发权重限制在 <code>w_euc</code> 与 <code>1.0</code> 的较小值，避免启发项比几何移动代价更激进。</p><p>当前三套主要配置均使用：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>how_many_corners = 8</span></span>
<span class="line"><span>allow_unknown = true</span></span>
<span class="line"><span>w_euc_cost = 1.0</span></span>
<span class="line"><span>w_traversal_cost = 2.0</span></span>
<span class="line"><span>use_final_approach_orientation = false</span></span></code></pre></div><h3 id="_5-4-两个权重分别控制什么" tabindex="-1">5.4 两个权重分别控制什么 <a class="header-anchor" href="#_5-4-两个权重分别控制什么" aria-label="Permalink to &quot;5.4 两个权重分别控制什么&quot;">​</a></h3><p>提高 <code>w_euc_cost</code>，更强调路径长度，结果倾向绷紧，但也可能更靠近障碍。</p><p>提高 <code>w_traversal_cost</code>，更强调 Inflation 代价，结果倾向走廊中部，但可能变长并扩展更多节点。</p><p>调 Theta* 不能只看这两个权重。Global Costmap 的 <code>inflation_radius</code> 与 <code>cost_scaling_factor</code> 决定算法究竟能“看见”多宽、多平缓的障碍代价坡面。</p><p><img src="`+d+'" alt="Theta* 的 g、h 与视线重连代价"></p><h2 id="六、搜索成功后如何变成一条-nav2-path" tabindex="-1">六、搜索成功后如何变成一条 Nav2 Path <a class="header-anchor" href="#六、搜索成功后如何变成一条-nav2-path" aria-label="Permalink to &quot;六、搜索成功后如何变成一条 Nav2 Path&quot;">​</a></h2><h3 id="_6-1-父指针从目标回到起点" tabindex="-1">6.1 父指针从目标回到起点 <a class="header-anchor" href="#_6-1-父指针从目标回到起点" aria-label="Permalink to &quot;6.1 父指针从目标回到起点&quot;">​</a></h3><p><code>backtrace()</code> 从目标节点开始，不断读取 <code>parent_id</code>，把每个栅格中心通过 <code>mapToWorld()</code> 转成世界坐标。得到的逆序序列再反转，形成起点到目标的任意角折线。</p><p>路径的转折点不是每个 A* 相邻栅格，而是父节点重连后保留下来的可见性关键点。</p><h3 id="_6-2-线性插值把长直线重新采密" tabindex="-1">6.2 线性插值把长直线重新采密 <a class="header-anchor" href="#_6-2-线性插值把长直线重新采密" aria-label="Permalink to &quot;6.2 线性插值把长直线重新采密&quot;">​</a></h3><p>任意角父链可能一段跨越很多栅格。<code>linearInterpolation()</code> 以 Costmap 分辨率为间距，在每个父链线段上补充 Pose，避免下游控制器只拿到极稀疏的折点。</p><p>这一步只做直线采样，不再次执行碰撞检查，也不做曲率优化。</p><h3 id="_6-3-末点朝向有两种语义" tabindex="-1">6.3 末点朝向有两种语义 <a class="header-anchor" href="#_6-3-末点朝向有两种语义" aria-label="Permalink to &quot;6.3 末点朝向有两种语义&quot;">​</a></h3><p><code>use_final_approach_orientation=false</code> 时，输出末 Pose 使用请求目标的方向。</p><p>设为 <code>true</code> 时，末 Pose 朝向由最后两个输出点的连线计算，让机器人沿最终接近方向到达，而不是在路径末端强行匹配目标 yaw。</p><p><img src="'+p+'" alt="父链回溯、世界坐标转换与路径插值"></p><h2 id="七、当前实现中必须看懂的边界" tabindex="-1">七、当前实现中必须看懂的边界 <a class="header-anchor" href="#七、当前实现中必须看懂的边界" aria-label="Permalink to &quot;七、当前实现中必须看懂的边界&quot;">​</a></h2><h3 id="_7-1-它没有目标容差回退" tabindex="-1">7.1 它没有目标容差回退 <a class="header-anchor" href="#_7-1-它没有目标容差回退" aria-label="Permalink to &quot;7.1 它没有目标容差回退&quot;">​</a></h3><p>Theta* 没有 NavFn 那种 <code>tolerance</code> 邻域搜索。目标栅格不安全或不可达时，结果就是空路径，不会自动选择目标附近的可达点。</p><h3 id="_7-2-同栅格快速路径的安全语义不同" tabindex="-1">7.2 同栅格快速路径的安全语义不同 <a class="header-anchor" href="#_7-2-同栅格快速路径的安全语义不同" aria-label="Permalink to &quot;7.2 同栅格快速路径的安全语义不同&quot;">​</a></h3><p>起终点落在同一栅格时，包装层只拒绝原始值等于 <code>LETHAL_OBSTACLE</code> 的栅格。该分支没有复用算法层 <code>isSafe()</code>，因此对 <code>253</code>、未知区和 <code>allow_unknown</code> 的解释与普通搜索分支并不完全一致。</p><h3 id="_7-3-优先队列没有-decrease-key" tabindex="-1">7.3 优先队列没有 decrease-key <a class="header-anchor" href="#_7-3-优先队列没有-decrease-key" aria-label="Permalink to &quot;7.3 优先队列没有 decrease-key&quot;">​</a></h3><p>节点已经在队列中时，如果找到更低代价，源码会直接修改该节点对象的 <code>f</code>，但不会重新压入队列，也不会重建堆。</p><p>标准 C++ <code>priority_queue</code> 不会因为指针指向对象的值改变而自动恢复堆序。这意味着队首顺序可能暂时不再严格对应最新 <code>f</code>。</p><h3 id="_7-4-主循环的队列与当前节点错开一拍" tabindex="-1">7.4 主循环的队列与当前节点错开一拍 <a class="header-anchor" href="#_7-4-主循环的队列与当前节点错开一拍" aria-label="Permalink to &quot;7.4 主循环的队列与当前节点错开一拍&quot;">​</a></h3><p>源码先处理 <code>curr_data</code>，再从队列取出下一节点。起点最初既是 <code>curr_data</code> 又留在队列中，因此可能被重复展开。</p><p>如果取出某个节点后队列恰好为空，下一轮不会再进入目标判断，随后 <code>queue_.empty()</code> 分支会报告失败。这个终止结构与常见的“先 pop、再判断目标”写法不同，需要专门的极小地图测试覆盖。</p><h3 id="_7-5-动态参数不完全重建派生状态" tabindex="-1">7.5 动态参数不完全重建派生状态 <a class="header-anchor" href="#_7-5-动态参数不完全重建派生状态" aria-label="Permalink to &quot;7.5 动态参数不完全重建派生状态&quot;">​</a></h3><p>配置阶段会把非法 <code>how_many_corners</code> 恢复为 <code>8</code>，动态回调却直接接受整数。大于固定移动表长度 <code>8</code> 的值会越界访问。</p><p>动态修改 <code>w_euc_cost</code> 时，源码也不会重新计算 <code>w_heuristic_cost=min(w_euc_cost,1.0)</code>。实车上更适合停用规划器后修改这类核心参数，再重新配置。</p><h3 id="_7-6-插值输出没有显式追加原始终点" tabindex="-1">7.6 插值输出没有显式追加原始终点 <a class="header-anchor" href="#_7-6-插值输出没有显式追加原始终点" aria-label="Permalink to &quot;7.6 插值输出没有显式追加原始终点&quot;">​</a></h3><p>当前插值循环只为每段写入段首和中间采样点，没有在循环结束后显式写入 <code>raw_path.back()</code>。输出末点可能停在目标栅格中心前一个分辨率以内，而末点方向仍会被赋成目标方向或接近方向。</p><h3 id="_7-7-costmap-锁覆盖完整计算" tabindex="-1">7.7 Costmap 锁覆盖完整计算 <a class="header-anchor" href="#_7-7-costmap-锁覆盖完整计算" aria-label="Permalink to &quot;7.7 Costmap 锁覆盖完整计算&quot;">​</a></h3><p><code>createPlan()</code> 从坐标检查开始持有 Costmap mutex，直到搜索、回溯和插值结束。复杂地图上，Theta* 的搜索耗时也会成为 Costmap 更新的阻塞时间。</p><h2 id="八、什么场景适合-theta" tabindex="-1">八、什么场景适合 Theta* <a class="header-anchor" href="#八、什么场景适合-theta" aria-label="Permalink to &quot;八、什么场景适合 Theta*&quot;">​</a></h2><h3 id="_8-1-开放空间与斜向走廊" tabindex="-1">8.1 开放空间与斜向走廊 <a class="header-anchor" href="#_8-1-开放空间与斜向走廊" aria-label="Permalink to &quot;8.1 开放空间与斜向走廊&quot;">​</a></h3><p>当真实最优方向不与地图轴对齐时，Theta* 能用长视线段减少八邻域 A* 的锯齿。</p><h3 id="_8-2-小型差速或全向机器人" tabindex="-1">8.2 小型差速或全向机器人 <a class="header-anchor" href="#_8-2-小型差速或全向机器人" aria-label="Permalink to &quot;8.2 小型差速或全向机器人&quot;">​</a></h3><p>算法搜索 <code>(x,y)</code>，不携带航向、最小转弯半径或倒车状态。它适合由下游控制器消化折点的小型差速和全向底盘。</p><h3 id="_8-3-不适合把车辆运动学交给规划器的场景" tabindex="-1">8.3 不适合把车辆运动学交给规划器的场景 <a class="header-anchor" href="#_8-3-不适合把车辆运动学交给规划器的场景" aria-label="Permalink to &quot;8.3 不适合把车辆运动学交给规划器的场景&quot;">​</a></h3><p>汽车型机器人若需要在全局搜索阶段保证曲率、朝向和倒车可行性，Smac Hybrid 或 State Lattice 更直接。Theta* 的直线可见不等于车辆能以合法转弯半径连接两段路径。</p><h2 id="九、结语" tabindex="-1">九、结语 <a class="header-anchor" href="#九、结语" aria-label="Permalink to &quot;九、结语&quot;">​</a></h2><p>Theta* 的核心可以压缩成一句话：先按 A* 发现节点，再用 Costmap 上的视线检查重写父指针。</p><p>真正决定结果的不是“有没有一条直线”，而是三层约束共同作用：栅格是否安全、沿线穿越代价是否值得、祖父节点直连是否降低累计 <code>g</code>。理解 <code>resetParent()</code>、<code>losCheck()</code> 与代价公式后，就能分清任意角路径、贴障程度、未知区策略和搜索速度分别该从哪里调。</p><p>同时也要尊重当前实现边界：它不搜索目标容差，不检查完整运动学，优先队列更新与终止循环还有需要回归测试守住的角落。Theta* 能把栅格路径拉直，但不会替机器人解决所有几何与工程问题。</p>',124)])])}const k=e(l,[["render",h]]);export{q as __pageData,k as default};
